<?php
declare(strict_types=1);require_once __DIR__.'/config/purchase_step14.php';$error=null;$sup=[];$monthly=[];$m=['billed'=>0.0,'returns'=>0.0,'paid'=>0.0,'outstanding'=>0.0,'overdue'=>0.0,'received'=>0,'pending'=>0];
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$m['billed']+=$st['total'];$m['returns']+=$st['return_credit'];$m['paid']+=$st['paid'];$m['outstanding']+=$st['outstanding'];if($st['receipt_status']==='received')$m['received']++;else$m['pending']++;if($st['outstanding']>0.009&&$b['due_date']&&$b['due_date']<date('Y-m-d'))$m['overdue']+=$st['outstanding'];}$sup=purchase_step14_suppliers($pdo,$orgId);$stmt=$pdo->prepare("SELECT DATE_FORMAT(invoice_date,'%Y-%m') month_key,COUNT(*) bills,SUM(total_amount) billed,SUM(return_credit) return_total,SUM(paid_amount) paid,SUM(GREATEST(0,total_amount-return_credit-paid_amount)) outstanding FROM purchase_bills WHERE organization_id=? AND status='active' GROUP BY DATE_FORMAT(invoice_date,'%Y-%m') ORDER BY month_key DESC LIMIT 18");$stmt->execute([$orgId]);$monthly=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function pa_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function pa_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Analytics - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Purchase Analytics</small></span></a><div class="os-top-actions"><a class="os-btn" href="supplier_payments.php">Payables</a><a class="os-btn" href="purchase_export.php">Export</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a href="purchase_bills.php"><i class="dot"></i>Bills</a><a href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a class="active" href="purchase_analytics.php"><i class="dot"></i>Analytics</a><a href="step14_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 14G • PURCHASE ANALYTICS</div><h1>See supplier exposure, receipt progress and actual purchase cash settlement.</h1><p>Totals come from active supplier bills, posted returns and active supplier payments; no stock or sales values are mixed into supplier payable analytics.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PURCHASE ANALYTICS LIVE':'Review required' ?></span><span class="os-chip"><?= count($sup) ?> suppliers</span><span class="os-chip"><?= count($monthly) ?> months</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Analytics diagnostic:</strong> <?= pa_h($error) ?></div><?php endif;?><section class="s10-kpis"><div class="s10-kpi"><small>Billed</small><strong><?= pa_m($m['billed']) ?></strong><span>Active supplier bills</span></div><div class="s10-kpi"><small>Outstanding</small><strong><?= pa_m($m['outstanding']) ?></strong><span><?= pa_m($m['overdue']) ?> overdue</span></div><div class="s10-kpi"><small>Paid</small><strong><?= pa_m($m['paid']) ?></strong><span>Active supplier payments</span></div><div class="s10-kpi"><small>Return Credits</small><strong><?= pa_m($m['returns']) ?></strong><span><?= $m['received'] ?> received • <?= $m['pending'] ?> pending bills</span></div></section><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-7"><h2>Supplier Exposure</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Supplier</th><th>Billed</th><th>Returns</th><th>Paid</th><th>Outstanding</th><th>Open Bills</th></tr></thead><tbody><?php foreach($sup as $s):?><tr><td><a href="supplier_detail.php?id=<?= (int)$s['id'] ?>"><b><?= pa_h($s['supplier_name']) ?></b></a><small><?= pa_h($s['supplier_code']) ?></small></td><td><?= pa_m($s['billed']) ?></td><td><?= pa_m($s['return_credit']) ?></td><td><?= pa_m($s['paid']) ?></td><td><b><?= pa_m($s['outstanding']) ?></b></td><td><?= (int)$s['open_bills'] ?></td></tr><?php endforeach;?><?php if(!$sup):?><tr><td colspan="6">No supplier activity yet.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-5"><h2>Monthly Purchase Trend</h2><div class="s10-list"><?php foreach($monthly as $r):?><div class="s10-row"><div><b><?= pa_h($r['month_key']) ?></b><small><?= (int)$r['bills'] ?> bills • Return <?= pa_m($r['return_total']) ?></small></div><strong><?= pa_m($r['billed']) ?></strong></div><?php endforeach;?><?php if(!$monthly):?><div class="s10-row"><div><b>No purchase months yet</b></div></div><?php endif;?></div></article></section><div class="os-footer-note"><strong>Analytics rule:</strong> purchase liability and cash settlement are shown separately from inventory valuation and Product Sale revenue.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
